    'policies_intro' => 'تفصل المجلة بين الادعاء العلمي والرأي المهني والقرار التحريري عبر قواعد شفافة قابلة للتدقيق.',
    'policy' => [
        'separation'=>['title'=>'تصنيف المحتوى','body'=>'البحث العلمي وحده يدخل التقديم والفحص والتحكيم المستقل. أما المقال المهني فيصدره المحرر المخول مباشرة ويبقى موسومًا دائمًا بأنه محتوى تحريري غير محكّم علميًا.'],
        'peer_review'=>['title'=>'التحكيم العلمي','body'=>'تخضع الأبحاث للفحص التحريري والتحكيم المستقل قبل قرار القبول، وتبقى هوية المحكّمين وملاحظاتهم السرية محمية.'],
        'originality_policy'=>['title'=>'الأصالة وفحص التشابه','body'=>'يجب أن يكون التقديم أصيلاً وغير مقدم بالتزامن إلى جهة أخرى. قد تستخدم التحرير فحص تشابه مشروعاً، لكن النتيجة دليل للتقييم وليست حكماً آلياً بسوء السلوك.'],
        'ai_policy'=>['title'=>'استخدام الذكاء الاصطناعي','body'=>'لا يُنسب التأليف لأداة ذكاء اصطناعي. يبقى المؤلف مسؤولاً عن الدقة والمصادر والسرية والحقوق، ويجب أن يصرح بالمساعدة الجوهرية في الكتابة أو التحليل أو الصور أو الترجمة أو معالجة البيانات. ولا يجوز للمحررين والمحكمين رفع مخطوطات سرية إلى أنظمة غير معتمدة.'],
        'ethics_policy'=>['title'=>'أخلاقيات البحث','body'=>'يصرّح المؤلفون عن الموافقات الأخلاقية والموافقة المستنيرة عند انطباقها، ولا تنشئ المجلة أو توحي بموافقات غير موجودة.'],
        'authorship_policy'=>['title'=>'التأليف والمساهمات','body'=>'يتطلب التأليف مساهمة فكرية ومسؤولية واضحة، وتُسجل الانتماءات وORCID وبيانات المساهمة عند تقديمها.'],
        'conflicts_policy'=>['title'=>'المصالح والتمويل','body'=>'يجب الإفصاح عن أي علاقة أو تمويل يمكن أن يؤثر بصورة معقولة في العمل أو تقييمه.'],
        'corrections_policy'=>['title'=>'التصحيحات والإصدارات','body'=>'لا تُستبدل النسخة المنشورة بصمت؛ ينشئ التغيير الجوهري تصحيحًا مرتبطًا بهوية وتاريخ وبصمة سلامة مستقلة.'],
        'retraction_policy'=>['title'=>'السحب','body'=>'يبقى السجل المسحوب ظاهرًا مع إشعار واضح حفاظًا على السجل العلمي ومنع اختفاء تاريخ الاستشهاد.'],
        'data_availability_policy'=>['title'=>'إتاحة البيانات وقابلية إعادة الإنتاج','body'=>'يجب أن يوضح البحث مكان إتاحة البيانات والبرمجيات والمواد الداعمة أو يشرح القيود الأخلاقية أو القانونية أو الأمنية، مع وصف المنهج بما يكفي للتقييم العلمي.'],
        'misconduct_policy'=>['title'=>'سوء السلوك البحثي','body'=>'تُفحص ادعاءات التلفيق أو التزوير أو الانتحال أو التعارض غير المعلن أو التلاعب بالتحكيم بسرية وبأدلة موثقة وحق في الرد، ثم يُتخذ تصحيح أو رفض أو سحب متناسب. ولا تُدّعى عضوية خارجية غير مثبتة.'],
        'appeals_policy'=>['title'=>'الشكاوى والاستئناف','body'=>'يجوز للمؤلف أو القارئ إرسال شكوى أو استئناف محدد ومدعوم بالأدلة إلى البريد الرسمي. يراجعه، متى أمكن، شخص لم يصدر القرار المختلف عليه؛ ولا يكفي الاختلاف وحده لعكس الحكم العلمي.'],
        'privacy_policy'=>['title'=>'حماية البيانات والسرية','body'=>'لا يظهر للعامة إلا وصف النشر اللازم. تبقى بيانات المؤلف والمخطوطات وهوية المحكم والتعليقات السرية مشفرة أو مقيدة الوصول ولا تستخدم إلا للتشغيل التحريري المشروع.'],
        'preservation_policy'=>['title'=>'الحفظ الرقمي','body'=>'تحتفظ النسخ المنشورة ببصمات تشفيرية وتاريخ غير قابل للاستبدال. ويتطلب الإطلاق نسخاً احتياطية محمية وحديثة، ولا تُدّعى مشاركة شبكة أرشفة خارجية إلا بعد تفعيل موثق.'],
        'licensing_policy'=>['title'=>'الحقوق والتراخيص','body'=>'يعرض كل سجل ترخيصه الفعلي، ولا يُفترض وجود ترخيص مفتوح ما لم يُعتمد صراحة.'],
        'fees_policy'=>['title'=>'الرسوم وتكاليف معالجة المقال','body'=>'تظهر سياسة الرسوم أو الإعفاء الحالية في معلومات النشر أدناه. لا يضمن أي دفع غير معلن التحكيم أو القبول أو النشر، ولا تغيّر العضوية المهنية المعايير التحريرية.'],
        'doi_policy'=>['title'=>'DOI وادعاءات الفهرسة','body'=>'لا يظهر DOI أو ISSN أو الفهرسة أو المقاييس إلا بعد التخصيص أو التحقق الرسمي، ولا تعرض المعرفات التجريبية كتسجيلات خارجية.'],
    ],
